#include "Managers/HorizonMatchesManager.h"
void UHorizonAsync_MatchesBase::Freeze(const UObject* W){World=W;auto* S=UHorizonBlueprintLibrary::GetHorizonSubsystem(W);OriginalSubsystem=S;if(S&&S->Auth){User=S->Auth->GetCurrentUser().UserId;Context=S->GetHttpClient()->GetRequestContextEpoch();}RegisterWithGameInstance(W);}
UHorizonSubsystem* UHorizonAsync_MatchesBase::Resolve(FString& Code){auto* S=UHorizonBlueprintLibrary::GetHorizonSubsystem(World.Get());if(!S||!S->Matches){Code=TEXT("SDK_NOT_CONNECTED");return nullptr;}if(S!=OriginalSubsystem.Get()||S->GetHttpClient()->GetRequestContextEpoch()!=Context){Code=TEXT("STALE_RESPONSE");return nullptr;}return S;}
UHorizonAsync_Matches* UHorizonAsync_Matches::GetMatches(const UObject* W){auto* A=NewObject<UHorizonAsync_Matches>();A->Freeze(W);A->Operation=TEXT("GetMatches");return A;}
void UHorizonAsync_Matches::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}const auto Done=FOnMatchesComplete::CreateUObject(this,&UHorizonAsync_Matches::Complete);if(Operation==TEXT("GetMatches")){S->Matches->GetMatches(User,Done);return;}Complete(false,{},TEXT("INVALID_REQUEST"),TEXT("Unknown original operation"));}
void UHorizonAsync_Matches::Complete(bool Ok,const FHorizonMyMatches& V,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,V,Code,Message);SetReadyToDestroy();}
