UHorizonAsync_MatchRead* UHorizonAsync_MatchRead::SubmitTurn(const UObject* W, const FString& MatchId, int64 ExpectedRevision, const TArray<uint8>& Data, bool bFinish){auto* A=NewObject<UHorizonAsync_MatchRead>();A->Freeze(W);A->Operation=TEXT("SubmitTurn");A->MatchId=MatchId;A->ExpectedRevision=ExpectedRevision;A->Data=Data;A->bFinish=bFinish;return A;}
void UHorizonAsync_MatchRead::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}const auto Done=FOnMatchComplete::CreateUObject(this,&UHorizonAsync_MatchRead::Complete);if(Operation==TEXT("GetMatch")){S->Matches->GetMatch(User,MatchId,Done);return;}if(Operation==TEXT("JoinMatch")){S->Matches->JoinMatch(User,MatchId,ExpectedRevision,Done);return;}if(Operation==TEXT("DeclineInvite")){S->Matches->DeclineInvite(User,MatchId,ExpectedRevision,Done);return;}if(Operation==TEXT("AdvanceTimeout")){S->Matches->AdvanceTimeout(User,MatchId,ExpectedRevision,Done);return;}if(Operation==TEXT("LeaveMatch")){S->Matches->LeaveMatch(User,MatchId,ExpectedRevision,Done);return;}if(Operation==TEXT("CancelMatch")){S->Matches->CancelMatch(User,MatchId,ExpectedRevision,Done);return;}if(Operation==TEXT("StartMatch")){S->Matches->StartMatch(User,MatchId,ExpectedRevision,TurnOrder,Done);return;}if(Operation==TEXT("SubmitTurn")){S->Matches->SubmitTurn(User,MatchId,ExpectedRevision,Data,bFinish,Done);return;}Complete(false,{},TEXT("INVALID_REQUEST"),TEXT("Unknown original operation"));}
void UHorizonAsync_MatchRead::Complete(bool Ok,const FHorizonMatchRead& V,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,V,Code,Message);SetReadyToDestroy();}
